export interface DashboardState {
  student: Student | null;
  courses: Course[];
  assignments: Assignment[];
  notifications: Notification[];
}

import type { Course, DashboardState } from "../shared/types/dashboard";

export type DashboardAction =
  | {
      type: "COURSES_LOADED";
      courses: Course[];
    }
  | {
      type: "COURSE_PROGRESS_UPDATED";
      courseId: number;
      progress: number;
    }
  | {
      type: "NOTIFICATION_READ";
      notificationId: number;
    };

export function dashboardReducer(
  state: DashboardState,
  action: DashboardAction
): DashboardState {
  switch (action.type) {
    case "COURSES_LOADED":
      return { ...state, courses: action.courses };
    case "COURSE_PROGRESS_UPDATED":
      return {
        ...state,
        courses: state.courses.map(course =>
          course.id === action.courseId
            ? { ...course, progress: action.progress }
            : course
        )
      };
    case "NOTIFICATION_READ":
      return {
        ...state,
        notifications: state.notifications.map(item =>
          item.id === action.notificationId
            ? { ...item, read: true }
            : item
        )
      };
    default: {
      const exhaustiveCheck: never = action;
      return exhaustiveCheck;
    }
  }
}

